 25→
 26→export const loader = async ({ request }: LoaderFunctionArgs) => {
 27→  const { session, admin } = await authenticate.admin(request);
 28→  const shop = session.shop;
 29→
 30→  const zipCodes = await db.zipCode.findMany({ where: { shop } });
 31→  const [deliveryRulesCount, waitlistCount, subscription] = await Promise.all([
 32→    db.deliveryRule.count({ where: { shop } }),
 33→    db.waitlistEntry.count({ where: { shop } }),
 34→    getShopSubscription(shop),
 35→  ]);
 36→
 37→  const stats = {
 38→    total: zipCodes.length,
 39→    allowed: zipCodes.filter((z) => z.type === "allowed").length,
 40→    blocked: zipCodes.filter((z) => z.type === "blocked").length,
 41→    deliveryRules: deliveryRulesCount,
 42→    waitlist: waitlistCount,
 43→  };
 44→
 45→  // Detect whether the App Embed is enabled in the active theme (GraphQL)
 46→  let appEmbedEnabled = false;
 47→  let activeThemeName: string | null = null;
 48→  let themeEditorUrl = `https://${shop}/admin/themes/current/editor`;
 49→  let themeEditorAppEmbedsUrl = `https://${shop}/admin/themes/current/editor?context=apps`;
 50→  try {
 51→    const themeResponse = await admin.graphql(`{
 52→      themes(first: 1, roles: MAIN) {
 53→        nodes {
 54→          id
 55→          name
 56→          files(filenames: ["config/settings_data.json"], first: 1) {
 57→            nodes {
 58→              body {
 59→                ... on OnlineStoreThemeFileBodyText {
 60→                  content
 61→                }
 62→              }
 63→            }
 64→          }
 65→        }
 66→      }
 67→    }`);
 68→    const themeData = (await themeResponse.json()) as {
 69→      data?: {
 70→        themes?: {
 71→          nodes?: Array<{
 72→            id: string;
 73→            name: string;
 74→            files?: {
 75→              nodes?: Array<{
 76→                body?: { content?: string };
 77→              }>;
 78→            };
 79→          }>;
 80→        };
 81→      };
 82→    };
 83→    const mainTheme = themeData?.data?.themes?.nodes?.[0];
 84→    if (mainTheme) {
 85→      const gidParts = mainTheme.id.split("/");
 86→      const numericId = gidParts[gidParts.length - 1];
 87→      activeThemeName = mainTheme.name;
 88→      themeEditorUrl = `https://${shop}/admin/themes/${numericId}/editor`;
 89→      themeEditorAppEmbedsUrl = `https://${shop}/admin/themes/${numericId}/editor?context=apps`;
 90→
 91→      let content = mainTheme.files?.nodes?.[0]?.body?.content;
 92→      if (content) {
 93→        /* eslint-disable @typescript-eslint/no-explicit-any */
 94→        // Strip leading comments (some themes prepend CSS/JS comments)
 95→        content = content.replace(/^\/\*[\s\S]*?\*\/\s*/, "").trim();
 96→        // Find the first { to start valid JSON
 97→        const jsonStart = content.indexOf("{");
 98→        if (jsonStart > 0) content = content.substring(jsonStart);
 99→
100→        let settingsData: any;
101→        try {
102→          settingsData = JSON.parse(content);
103→        } catch {
104→          return {
105→            stats, subscription, appEmbedEnabled, activeThemeName,
106→            themeEditorUrl, themeEditorAppEmbedsUrl,
107→          };
108→        }
109→        const apiKey = process.env.SHOPIFY_API_KEY ?? "";
110→
111→        const blocks = settingsData?.current?.blocks ?? {};
112→        const embedBlocks = Object.entries(blocks).filter(([, block]) => {
113→          const b = block as { type?: string };
114→          const t = b.type ?? "";
115→          return t.includes("app_embed") || t.includes("app-embed");
116→        });
117→
118→        // Check each embed block
119→        for (const [key, block] of embedBlocks) {
120→          const b = block as { type?: string; disabled?: boolean };
121→          if (b.disabled === true) continue;
122→          const typeStr = b.type ?? "";
123→          const keyStr = key;
124→          // Match by API key or app handle
125→          if (
126→            (apiKey && (keyStr.includes(apiKey) || typeStr.includes(apiKey))) ||
127→            keyStr.includes("zip-code") || typeStr.includes("zip-code") ||
128→            keyStr.includes("zip_code") || typeStr.includes("zip_code")
129→          ) {
130→            appEmbedEnabled = true;
131→            break;
132→          }
133→        }
134→
135→        // Fallback: raw string scan
136→        if (!appEmbedEnabled) {
137→          const contentLower = content.toLowerCase();
138→          const hasEmbed = contentLower.includes("app_embed");
139→          const hasOurApp =
140→            (apiKey && contentLower.includes(apiKey.toLowerCase())) ||
141→            contentLower.includes("zip-code-checker") ||
142→            contentLower.includes("zip-code-widget");
143→          if (hasEmbed && hasOurApp) {
144→            // Check not disabled
145→            const notDisabled = !contentLower.includes('"disabled":true');
146→            if (notDisabled) appEmbedEnabled = true;
147→          }
148→        }
149→
150→        /* eslint-enable @typescript-eslint/no-explicit-any */
151→      }
152→    }
153→  } catch {
154→    // Theme detection failed — leave appEmbedEnabled as false
155→  }
156→
157→  return {
158→    stats,
159→    subscription,
160→    appEmbedEnabled,
161→    activeThemeName,
162→    themeEditorUrl,
163→    themeEditorAppEmbedsUrl,
164→  };
165→};
