264→
265→          {/* ─── 2. STATS ─── */}
266→          {!isEmpty && (
267→            <Card>
268→              <BlockStack gap="400">
269→                <InlineGrid columns={{ xs: 2, sm: 3, md: 5 }} gap="400">
