278→                    </Text>
279→                    <Text as="p" variant="bodySm" tone="subdued">
280→                      Zip codes
281→                    </Text>
282→                  </BlockStack>
283→
284→                  <BlockStack gap="100">
285→                    <Text as="p" variant="headingXl" fontWeight="bold" tone="success">
286→                      {stats.allowed}
287→                    </Text>
288→                    <Text as="p" variant="bodySm" tone="subdued">
289→                      Serviceable
290→                    </Text>
291→                  </BlockStack>
292→
293→                  <BlockStack gap="100">
294→                    <Text as="p" variant="headingXl" fontWeight="bold" tone={stats.blocked > 0 ? "critical" : "subdued"}>
295→                      {stats.blocked}
296→                    </Text>
297→                    <Text as="p" variant="bodySm" tone="subdued">
298→                      Blocked
