  1→import { useState, useCallback } from "react";
  2→import type {
  3→  ActionFunctionArgs,
  4→  HeadersFunction,
  5→  LoaderFunctionArgs,
  6→} from "react-router";
  7→import { useFetcher, useLoaderData, useNavigate, useRouteError } from "react-router";
  8→import { useAppBridge } from "@shopify/app-bridge-react";
  9→import { authenticate } from "../shopify.server";
 10→import { boundary } from "@shopify/shopify-app-react-router/server";
 11→import db from "../db.server";
 12→import { getShopSubscription } from "../billing.server";
 13→import { PLAN_LIMITS } from "../plans";
 14→import {
 15→  Page,
 16→  Layout,
 17→  Card,
 18→  BlockStack,
 19→  InlineStack,
 20→  InlineGrid,
 21→  Text,
 22→  Badge,
 23→  Button,
 24→  TextField,
 25→  Select,
 26→  Modal,
 27→  DataTable,
 28→  EmptyState,
 29→  Divider,
 30→  Box,
 31→  Tooltip,
 32→  Checkbox,
 33→  Banner,
 34→} from "@shopify/polaris";
 35→import { PlusIcon, DeleteIcon, EditIcon } from "@shopify/polaris-icons";
 36→
 37→const DAYS_OPTIONS = [
 38→  { label: "Monday", value: "Mon" },
 39→  { label: "Tuesday", value: "Tue" },
 40→  { label: "Wednesday", value: "Wed" },
 41→  { label: "Thursday", value: "Thu" },
 42→  { label: "Friday", value: "Fri" },
 43→  { label: "Saturday", value: "Sat" },
 44→  { label: "Sunday", value: "Sun" },
 45→];
 46→
 47→export const loader = async ({ request }: LoaderFunctionArgs) => {
 48→  const { session } = await authenticate.admin(request);
 49→  const shop = session.shop;
 50→
 51→  const [rules, zones, subscription] = await Promise.all([
 52→    db.deliveryRule.findMany({
 53→      where: { shop },
 54→      orderBy: { priority: "asc" },
 55→    }),
 56→    db.zipCode.findMany({
 57→      where: { shop, zone: { not: null } },
 58→      select: { zone: true },
 59→      distinct: ["zone"],
 60→    }),
 61→    getShopSubscription(shop),
 62→  ]);
 63→
 64→  return {
 65→    rules,
 66→    zones: zones.map((z) => z.zone).filter(Boolean) as string[],
 67→    subscription,
 68→  };
 69→};
 70→
 71→export const action = async ({ request }: ActionFunctionArgs) => {
 72→  const { session } = await authenticate.admin(request);
 73→  const shop = session.shop;
 74→  const formData = await request.formData();
 75→  const intent = formData.get("intent");
 76→
 77→  if (intent === "create" || intent === "update") {
 78→    const id = String(formData.get("id") || "");
 79→    const name = String(formData.get("name") || "").trim();
 80→    const zone = String(formData.get("zone") || "").trim() || null;
 81→    const zipCodes = String(formData.get("zipCodes") || "").trim() || null;
 82→    const minOrderAmount = formData.get("minOrderAmount")
 83→      ? parseFloat(String(formData.get("minOrderAmount")))
 84→      : null;
 85→    const deliveryFee = formData.get("deliveryFee")
 86→      ? parseFloat(String(formData.get("deliveryFee")))
 87→      : null;
 88→    const freeShippingAbove = formData.get("freeShippingAbove")
 89→      ? parseFloat(String(formData.get("freeShippingAbove")))
 90→      : null;
 91→    const estimatedDays =
 92→      String(formData.get("estimatedDays") || "").trim() || null;
 93→    const cutoffTime =
 94→      String(formData.get("cutoffTime") || "").trim() || null;
 95→    const daysOfWeek =
 96→      String(formData.get("daysOfWeek") || "").trim() || null;
 97→    const priority = parseInt(String(formData.get("priority") || "0"), 10);
 98→
 99→    if (!name) return { error: "Rule name is required." };
100→
101→    const data = {
102→      name,
103→      zone,
104→      zipCodes,
105→      minOrderAmount,
106→      deliveryFee,
107→      freeShippingAbove,
108→      estimatedDays,
109→      cutoffTime,
110→      daysOfWeek,
111→      priority,
112→    };
113→
114→    if (intent === "update" && id) {
115→      await db.deliveryRule.update({ where: { id }, data });
116→      return { success: true, action: "updated" };
117→    } else {
118→      // Plan-gating: check limits before creating a new rule
119→      const subscription = await getShopSubscription(shop);
120→      const { maxDeliveryRules, label: planLabel } = subscription.limits;
121→
122→      if (maxDeliveryRules === 0) {
123→        return {
124→          error:
125→            "Delivery rules are not available on the Free plan. Upgrade to Starter or Pro.",
126→        };
127→      }
128→
129→      if (isFinite(maxDeliveryRules)) {
130→        const currentCount = await db.deliveryRule.count({ where: { shop } });
131→        if (currentCount >= maxDeliveryRules) {
132→          return {
133→            error: `You've reached the ${maxDeliveryRules} delivery rule limit on the ${planLabel} plan. Upgrade to Pro for unlimited rules.`,
134→          };
135→        }
136→      }
137→
138→      await db.deliveryRule.create({ data: { shop, ...data } });
139→      return { success: true, action: "created" };
140→    }
141→  }
142→
143→  if (intent === "delete") {
144→    const id = String(formData.get("id"));
145→    await db.deliveryRule.delete({ where: { id } });
146→    return { success: true, action: "deleted" };
147→  }
148→
149→  if (intent === "toggle") {
150→    const id = String(formData.get("id"));
151→    const isActive = formData.get("isActive") === "true";
152→    await db.deliveryRule.update({
153→      where: { id },
154→      data: { isActive: !isActive },
155→    });
156→    return { success: true, action: "toggled" };
157→  }
158→
159→  return null;
160→};
