113→   113→   113→export const action = async ({ request }: ActionFunctionArgs) => {
114→   114→   114→  const { session } = await authenticate.admin(request);
115→   115→   115→  const shop = session.shop;
116→   116→   116→  const formData = await request.formData();
117→   117→   117→  const intent = formData.get("intent");
118→   118→   118→
119→   119→   119→  if (intent === "add") {
120→   120→   120→    const zipCode = String(formData.get("zipCode")).trim().toUpperCase();
121→   121→   121→    const label = String(formData.get("label") || "").trim();
122→   122→   122→    const zone = String(formData.get("zone") || "").trim();
123→   123→   123→    const message = String(formData.get("message") || "").trim();
124→   124→   124→    const eta = String(formData.get("eta") || "").trim();
125→   125→   125→    const type = String(formData.get("type") || "allowed");
126→   126→   126→    const codAvailable =
127→   127→   127→      formData.get("codAvailable") === "true"
128→   128→   128→        ? true
129→   129→   129→        : formData.get("codAvailable") === "false"
130→   130→   130→          ? false
131→   131→   131→          : null;
132→   132→   132→    const returnPolicy = (formData.get("returnPolicy") as string | null) || null;
133→   133→   133→
134→   134→   134→    if (!zipCode) return { error: "Zip code is required." };
135→   135→   135→
136→   136→   136→    const subscription = await getShopSubscription(shop);
137→   137→   137→    const limits = PLAN_LIMITS[subscription.planTier];
138→   138→   138→
139→   139→   139→    if (type === "blocked" && !limits.allowBlocked) {
140→   140→   140→      return {
141→   141→   141→        error:
142→   142→   142→          "Blocked zip codes are not available on your current plan. Upgrade to Pro or Ultimate to use blocked zip codes.",
143→   143→   143→        upgradeRequired: true,
144→   144→   144→      };
145→   145→   145→    }
146→   146→   146→
147→   147→   147→    const currentCount = await db.zipCode.count({ where: { shop } });
148→   148→   148→    if (limits.maxZipCodes !== Infinity && currentCount >= limits.maxZipCodes) {
149→   149→   149→      const upgradeTarget =
150→   150→   150→        subscription.planTier === "free" ? "Starter" : "Pro";
151→   151→   151→      return {
152→   152→   152→        error: `You have reached the ${limits.maxZipCodes} zip code limit on the ${limits.label} plan. Upgrade to ${upgradeTarget} for a higher limit.`,
153→   153→   153→        upgradeRequired: true,
154→   154→   154→      };
155→   155→   155→    }
156→   156→   156→
157→   157→   157→    try {
158→   158→   158→      await db.zipCode.create({
159→   159→   159→        data: {
160→   160→   160→          shop,
161→   161→   161→          zipCode,
162→   162→   162→          label: label || null,
163→   163→   163→          zone: zone || null,
164→   164→   164→          message: message || null,
165→   165→   165→          eta: eta || null,
166→   166→   166→          type,
167→   167→   167→          codAvailable: codAvailable ?? undefined,
168→   168→   168→          returnPolicy: returnPolicy ?? undefined,
169→   169→   169→        },
170→   170→   170→      });
171→   171→   171→      return { success: true, action: "added", zipCode };
172→   172→   172→    } catch {
173→   173→   173→      return { error: `Zip code "${zipCode}" already exists.` };
174→   174→   174→    }
175→   175→   175→  }
176→   176→   176→
177→   177→   177→  if (intent === "delete") {
178→   178→   178→    const id = String(formData.get("id"));
179→   179→   179→    try {
180→   180→   180→      await db.zipCode.delete({ where: { id } });
181→   181→   181→      return { success: true, action: "deleted" };
182→   182→   182→    } catch {
183→   183→   183→      return { error: "Failed to delete zip code." };
184→   184→   184→    }
185→   185→   185→  }
186→   186→   186→
187→   187→   187→  if (intent === "update") {
188→   188→   188→    const id = String(formData.get("id"));
189→   189→   189→    const zipCode = String(formData.get("zipCode")).trim().toUpperCase();
190→   190→   190→    const label = String(formData.get("label") || "").trim();
191→   191→   191→    const zone = String(formData.get("zone") || "").trim();
192→   192→   192→    const message = String(formData.get("message") || "").trim();
193→   193→   193→    const eta = String(formData.get("eta") || "").trim();
194→   194→   194→    const type = String(formData.get("type") || "allowed");
195→   195→   195→    const isActive = formData.get("isActive") === "true";
196→   196→   196→    const codAvailable =
197→   197→   197→      formData.get("codAvailable") === "true"
198→   198→   198→        ? true
199→   199→   199→        : formData.get("codAvailable") === "false"
200→   200→   200→          ? false
201→   201→   201→          : null;
202→   202→   202→    const returnPolicy = (formData.get("returnPolicy") as string | null) || null;
203→   203→   203→
204→   204→   204→    if (!zipCode) return { error: "Zip code is required." };
205→   205→   205→
206→   206→   206→    try {
207→   207→   207→      await db.zipCode.update({
208→   208→   208→        where: { id },
209→   209→   209→        data: {
210→   210→   210→          zipCode,
211→   211→   211→          label: label || null,
212→   212→   212→          zone: zone || null,
213→   213→   213→          message: message || null,
214→   214→   214→          eta: eta || null,
215→   215→   215→          type,
216→   216→   216→          isActive,
217→   217→   217→          codAvailable,
218→   218→   218→          returnPolicy,
219→   219→   219→        },
220→   220→   220→      });
221→   221→   221→      return { success: true, action: "updated", zipCode };
222→   222→   222→    } catch {
223→   223→   223→      return { error: `Failed to update zip code "${zipCode}". It may already exist.` };
224→   224→   224→    }
225→   225→   225→  }
226→   226→   226→
227→   227→   227→  if (intent === "toggle") {
228→   228→   228→    const id = String(formData.get("id"));
229→   229→   229→    const isActive = formData.get("isActive") === "true";
230→   230→   230→    try {
231→   231→   231→      await db.zipCode.update({
232→   232→   232→        where: { id },
233→   233→   233→        data: { isActive: !isActive },
234→   234→   234→      });
235→   235→   235→      return { success: true, action: "toggled" };
236→   236→   236→    } catch {
237→   237→   237→      return { error: "Failed to toggle zip code status." };
238→   238→   238→    }
239→   239→   239→  }
240→   240→   240→
241→   241→   241→  if (intent === "check") {
242→   242→   242→    const zipCode = String(formData.get("checkZip")).trim().toUpperCase();
243→   243→   243→    try {
244→   244→   244→      const found = await db.zipCode.findUnique({
245→   245→   245→        where: { shop_zipCode: { shop, zipCode } },
246→   246→   246→      });
247→   247→   247→      if (!found) return { checkResult: { found: false, zipCode } };
248→   248→   248→      return { checkResult: { found: true, zipCode, record: found } };
249→   249→   249→    } catch {
250→   250→   250→      return { error: "Failed to check zip code." };
251→   251→   251→    }
252→   252→   252→  }
253→   253→   253→
254→   254→   254→  if (intent === "bulk-import") {
255→   255→   255→    const csvData = String(formData.get("csvData") || "");
256→   256→   256→    if (!csvData.trim()) return { error: "No CSV data provided." };
257→   257→   257→
258→   258→   258→    const subscription = await getShopSubscription(shop);
259→   259→   259→    const limits = PLAN_LIMITS[subscription.planTier];
260→   260→   260→
261→   261→   261→    if (!limits.csvImport) {
262→   262→   262→      const upgradeTarget =
263→   263→   263→        subscription.planTier === "free" ? "Starter" : "Pro";
264→   264→   264→      return {
265→   265→   265→        error: `CSV import is not available on the ${limits.label} plan. Upgrade to ${upgradeTarget} to import zip codes via CSV.`,
266→   266→   266→        upgradeRequired: true,
267→   267→   267→      };
268→   268→   268→    }
269→   269→   269→
270→   270→   270→    const lines = csvData
271→   271→   271→      .split("\n")
272→   272→   272→      .map((l) => l.trim())
273→   273→   273→      .filter((l) => l.length > 0);
274→   274→   274→
275→   275→   275→    // Skip header row if present
276→   276→   276→    const startIdx =
277→   277→   277→      lines.length > 0 &&
278→   278→   278→      lines[0].toLowerCase().includes("zip")
279→   279→   279→        ? 1
280→   280→   280→        : 0;
281→   281→   281→
282→   282→   282→    const currentCount = await db.zipCode.count({ where: { shop } });
283→   283→   283→    let imported = 0;
284→   284→   284→    let skipped = 0;
285→   285→   285→    const errors: string[] = [];
286→   286→   286→
287→   287→   287→    for (let i = startIdx; i < lines.length; i++) {
288→   288→   288→      const cols = parseCsvRow(lines[i]);
289→   289→   289→      const zipCode = (cols[0] || "").toUpperCase();
290→   290→   290→      if (!zipCode) continue;
